create or replace function public.validate_location_photo_checkin_attribution() returns trigger language plpgsql security definer set search_path='public','auth','extensions','pg_temp' as $function$ declare c record; uid uuid:=auth.uid(); begin if new.check_in_id is null then return new; end if; select user_id,location_id into c from public.check_ins where id=new.check_in_id; if not found then raise exception 'CHECK_IN_NOT_FOUND'; end if; if c.location_id<>new.location_id then raise exception 'CHECK_IN_LOCATION_MISMATCH'; end if; if c.user_id<>coalesce(new.user_id,uid) then raise exception 'CHECK_IN_USER_MISMATCH'; end if; return new; end; $function$;
drop trigger if exists validate_location_photo_checkin_attribution on public.location_photos;
create trigger validate_location_photo_checkin_attribution before insert or update of check_in_id,location_id,user_id on public.location_photos for each row execute function public.validate_location_photo_checkin_attribution();
comment on function public.validate_location_photo_checkin_attribution() is 'Prevents a location photo from being attributed to a check-in belonging to a different user or location.';
